class Solution {
public:
    int secondsToRemoveOccurrences(std::string s) {
        int zeros = 0, ans = 0;
        for (char ch : s) {
            if (ch == '0') zeros++;
            else if (zeros > 0) ans = std::max(ans + 1, zeros);
        }
        return ans;
    }
};

class Solution {
    public int secondsToRemoveOccurrences(String s) {
        int zeros = 0, ans = 0;
        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            if (ch == '0') zeros++;
            else if (zeros > 0) ans = Math.max(ans + 1, zeros);
        }
        return ans;
    }
}

var secondsToRemoveOccurrences = function(s) {
    let zeros = 0, ans = 0;
    for (const ch of s) {
        if (ch === '0') zeros++;
        else if (zeros > 0) ans = Math.max(ans + 1, zeros);
    }
    return ans;
};
